package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;public final class RefundModels{private RefundModels(){}public record Payment(long id,long orderId,String orderNumber,String methodCode,String methodName,BigDecimal amount,BigDecimal refunded,String status,LocalDateTime paidAt,byte[]version){public Payment{version=version.clone();}@Override public byte[]version(){return version.clone();}public BigDecimal remaining(){return amount.subtract(refunded);}@Override public String toString(){return orderNumber+" · "+methodName+" · "+remaining();}}public record Refund(long id,long paymentId,String orderNumber,String method,String user,BigDecimal amount,String reason,String reference,String notes,LocalDateTime refundedAt){}public record Catalog(List<Payment>payments,List<Refund>refunds){public Catalog{payments=List.copyOf(payments);refunds=List.copyOf(refunds);}}}
